mapper.select:
SELECT * FROM ( SELECT inner_query.*, ROWNUM AS rnum FROM ( SELECT p.*, u.nickname, u.profile_img, u.grade, (SELECT COUNT(*) FROM comments c WHERE c.postno = p.postno) AS count_comments, (SELECT COUNT(*) FROM post_likes l WHERE l.postno = p.postno) AS count_likes FROM POSTS p LEFT JOIN USERS u ON (p.writer = u.userid)
AND board_type != 'notice'
AND board_type = #{boardType, jdbcType=VARCHAR}
AND p.postno = #{postNo, jdbcType=NUMERIC}
AND writer = #{writer, jdbcType=VARCHAR}
AND report_yn = 1
AND notice_yn = 0
ORDER BY notice_yn DESC, p.created_at DESC ) inner_query WHERE ROWNUM <= #{limit} ) WHERE rnum > #{offset}

